const catalog: Record<Lang, Record<string, string>> = {
  ko, en, zh, es, ja, fr, de, nl, id,
}

function deviceDefault(): Lang {
  const p = (navigator.language || 'en').toLowerCase()
  const hit = LANGS.find((l) => p.startsWith(l.code))
  return hit ? hit.code : 'en'
}

interface I18nCtx { lang: Lang; setLang: (l: Lang) => void; t: (k: string, ...a: (string | number)[]) => string }
const Ctx = createContext<I18nCtx>(null as any)

export function I18nProvider({ initial, onChange, children }: { initial?: Lang | null; onChange?: (l: Lang) => void; children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initial ?? deviceDefault())
  const setLang = useCallback((l: Lang) => { setLangState(l); onChange?.(l) }, [onChange])
  const t = useCallback((k: string, ...args: (string | number)[]) => {
    const s = catalog[lang]?.[k] ?? catalog.en[k] ?? k
    return args.length ? s.replace(/\{(\d+)\}/g, (_m, i) => String(args[Number(i)] ?? '')) : s
  }, [lang])
  const value = useMemo(() => ({ lang, setLang, t }), [lang, setLang, t])
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>
}
export const useI18n = () => useContext(Ctx)
